function initCA() {

  var res = parseInt(random(100) < 50 ? random(500, 8000) : random(8000, 100000));
  drawer = new Wolframdrawer(new Grid({
    x: border,
    y: border,
    w: width - 2 * border,
    h: height - 2 * border,
    size: res
  }));
  if (drawer.grid.size() < 8000) {
    drawer.initChildren();
  }
  drawer.initDrawingStack();

  background(255);

}

function mousePressed() {
